function ensureDefaults(){for(const key of Object.values(STORAGE))if(state[key]===undefined)state[key]={}}
function stableSlug(value){return String(value||'exercise').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'exercise'}
function exerciseId(section,name){return `exercise:${stableSlug(section)}:${stableSlug(name)}`}
