function catalogImages(section,name){if(!IMAGE_CATEGORIES.has(section))return null;const id=exerciseId(section,name),primary=CATALOG_IMAGE_FILES[id];return primary?{primary,secondary:'',altPrimary:CATALOG_IMAGE_ALT[id]||`${name} depicted exercise position`,altSecondary:''}:null}
function normalizeImages(value,fallback){const source=value??fallback;if(!source||typeof source!=='object')return null;const images={primary:String(source.primary||''),secondary:String(source.secondary||''),altPrimary:String(source.altPrimary||''),altSecondary:String(source.altSecondary||'')};return images.primary||images.secondary?images:null}
function movementCue(name){const n=name.toLowerCase();if(n.includes('squat')||n.includes('wall sit'))return'Bend the hips and knees while the knees track over the toes, then drive through the whole foot to return.';if(n.includes('deadlift')||n.includes('pull-through'))return'Hinge at the hips with a braced, neutral spine, move the load close to the body, then stand by extending the hips.';if(n.includes('lunge')||n.includes('split squat'))return'Step into a stable stance, lower both knees under control, and press through the front foot to rise without wobbling.';if(n.includes('step-up'))return'Place the whole working foot on the step, drive through that leg to stand tall, then lower slowly without dropping.';if(n.includes('chest press')||n.includes('bench press')||n.includes('push-up'))return'Lower the hands or handles toward chest level with elbows controlled, then press away until the arms are long without locking.';if(n.includes('shoulder press')||n.includes('overhead press'))return'Press from shoulder height overhead while keeping ribs stacked, then lower to the starting position under control.';if(n.includes('row')&&!n.includes('rowing machine'))return'Pull the handle or weight toward the ribs by driving the elbows back; pause briefly, then return until the arms are long.';if(n.includes('pulldown')||n.includes('pull-up'))return'Draw the elbows down toward the ribs, lift the chest slightly, and return slowly without shrugging or swinging.';if(n.includes('curl'))return'Keep the upper arm quiet, bend the elbow to bring the resistance up, then lower fully and slowly.';if(n.includes('triceps')||n.includes('skull crusher')||n.includes('dip'))return'Keep the shoulders stable, straighten the elbows against resistance, and return only as far as the elbows and shoulders stay comfortable.';if(n.includes('lateral raise'))return'Raise the arms out to the sides with soft elbows to about shoulder height, then lower slowly.';if(n.includes('front raise'))return'Raise the arms forward to about shoulder height without leaning back, then lower under control.';if(n.includes('fly'))return'Move the arms through a wide arc with soft elbows, stop at a comfortable chest or shoulder stretch, then reverse the arc.';if(n.includes('calf raise'))return'Rise through the balls of the feet, pause at the top, then lower the heels slowly through a comfortable range.';if(n.includes('leg press'))return'Lower the platform by bending the knees toward a comfortable depth, then press through the feet without locking the knees.';if(n.includes('leg extension'))return'Straighten the knees smoothly, pause short of a hard lockout, then lower the pad slowly.';if(n.includes('leg curl'))return'Bend the knees to move the pad toward the body, pause, then return slowly without lifting the hips.';if(n.includes('crunch'))return'Brace the abdomen and curl the ribs toward the pelvis without pulling the head, then uncurl slowly.';if(n.includes('back extension')||n.includes('superman'))return'Lift only until the trunk is aligned and the back remains comfortable, then return slowly without over-arching.';if(n.includes('plank'))return'Hold a straight line from head through hips, brace the abdomen and glutes, and keep the shoulders stacked over their support.';if(n.includes('bridge'))return'Press through the feet and squeeze the glutes to lift the hips until the trunk and thighs align, then lower slowly.';if(n.includes('walk'))return'Walk with an easy heel-to-toe stride, relaxed shoulders, and a pace that permits controlled breathing.';if(n.includes('run')||n.includes('jog'))return'Use short, quiet steps with the torso tall; increase speed or time gradually rather than forcing the pace.';if(n.includes('bike'))return'Pedal smoothly with the knees tracking forward and maintain a cadence and resistance you can control.';if(n.includes('swim')||['freestyle','breaststroke','backstroke','butterfly'].some(x=>n.includes(x)))return'Use smooth coordinated strokes and turns, maintain a sustainable rhythm, and rest at the wall before technique breaks down.';if(n.includes('stretch')||n.includes('pose'))return'Move gradually into the named position until a mild stretch is felt, hold without bouncing, then release slowly.';if(n.includes('rotation')||n.includes('torso'))return'Rotate through a comfortable range while the pelvis stays stable, then return slowly to center.';return`Perform ${name} through a smooth, comfortable range, pause where control is greatest, and return slowly to the start.`}
function catalogInstructions(section,item){const [name,muscle,,reps,,hint]=item,isStretch=section==='Stretching'||section==='Yoga',isIsometric=section==='Isometrics'||/hold|plank|wall sit|pose/i.test(name),isBand=section==='Resistance Bands',isCardio=['Aerobics','Swimming','Tai Chi'].includes(section),isMachine=section==='Gym Machines';let setup=isMachine?`Adjust the ${name} machine seat, pads, and range stop so the working joint lines up with the machine pivot; choose a resistance that permits controlled repetitions.`:isBand?`Inspect the band for cracks or thinning, anchor it securely, and take a stable stance with light tension before starting ${name}.`:isCardio?`Use suitable footwear or equipment for ${name}; begin at an easy pace with upright, balanced posture.`:isStretch?`Take a stable starting position for ${name}, support yourself if needed, and align the joints without forcing the ${muscle.toLowerCase()}.`:`Set up for ${name} with a stable base, neutral spine, and the resistance balanced before the first repetition.`;let movement=movementCue(name);if(isIsometric)movement=`Assume the ${name} position with the ${muscle.toLowerCase()} engaged. Hold for ${reps||'10–30 seconds'} without changing joint position, then reduce tension and return slowly.`;const breathing=isIsometric?'Breathe normally throughout the hold; never hold your breath. Exhale gently as you release the contraction.':isCardio?'Breathe rhythmically. Keep an intensity that allows steady breathing, and slow down if breathing becomes uncontrolled.':'Exhale during the effort and inhale during the controlled return; do not brace by holding your breath.';const formTips=[hint||`Keep ${muscle.toLowerCase()} engaged.`,isCardio?'Build duration or intensity gradually while posture remains steady.':'Lift and lower under control, keep joints aligned, and stop the repetition when form changes.'];const avoid=isStretch?['Do not bounce, force the range, or twist a joint to gain extra motion.']:isBand?['Do not use a damaged or loosely anchored band, let tension disappear, or release it toward the face or body.','Avoid leaning, jerking, or using momentum to finish a repetition.']:isCardio?['Avoid sudden large increases in pace, resistance, distance, or duration.','Do not continue when posture, balance, or coordination deteriorates.']:['Avoid swinging, bouncing, joint lockout, or using momentum to move the resistance.','Do not continue a repetition after alignment or a neutral spine can no longer be maintained.'];const safety=isStretch?'Stay within a comfortable stretch. Release gradually and stop for sharp pain, numbness, or tingling.':isCardio?'Slow down or stop for pain, dizziness, chest pain, unusual shortness of breath, numbness, or loss of balance.':isBand?'Maintain band tension and control the return to prevent snap-back. Stop before pain or loss of alignment.':'Use a comfortable range of motion and stop the set for sharp pain, loss of control, or inability to complete the lowering phase safely.';return{setup,movement,breathing,formTips,avoid,safety}}
function normalizeInstructions(value,fallback){const source=value??fallback;if(typeof source==='string')return{setup:'Use a stable starting position and prepare any equipment before beginning.',movement:source,breathing:'Breathe continuously; exhale during effort and inhale during the return.',formTips:[],avoid:[],safety:'Stop for sharp pain, dizziness, numbness, or loss of control.'};if(!source||typeof source!=='object')return null;return{setup:String(source.setup||''),movement:String(source.movement||''),breathing:String(source.breathing||''),formTips:Array.isArray(source.formTips)?source.formTips.map(String):[],avoid:Array.isArray(source.avoid)?source.avoid.map(String):[],safety:String(source.safety||'')}}
function instructionHtml(instructions,name,images){const x=normalizeInstructions(instructions),pics=normalizeImages(images);if(!x)return`<details class="exerciseInstructions"><summary>Instructions</summary><div class="exerciseInstructionBody"><p>No instructions available.</p></div></details>`;const list=items=>items.length?`<ul>${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`:'<p>None listed.</p>',imageList=pics?[['primary','altPrimary'],['secondary','altSecondary']].filter(([key])=>pics[key]).map(([key,alt])=>`<a class="exerciseInstructionImageLink" href="${escapeHtml(pics[key])}" target="_blank" rel="noopener" aria-label="Open larger ${escapeHtml(name)} illustration"><img class="exerciseInstructionImage" src="${escapeHtml(pics[key])}" alt="${escapeHtml(pics[alt]||`Instructional illustration of ${name}`)}" loading="lazy"></a>`).join(''):'';return`<details class="exerciseInstructions"><summary aria-label="Show instructions for ${escapeHtml(name)}">Instructions</summary><div class="exerciseInstructionBody">${imageList?`<div class="exerciseInstructionImages">${imageList}</div>`:''}<h4>Setup</h4><p>${escapeHtml(x.setup)}</p><h4>Movement</h4><p>${escapeHtml(x.movement)}</p><h4>Breathing</h4><p>${escapeHtml(x.breathing)}</p><h4>Form tips</h4>${list(x.formTips)}<h4>Avoid</h4>${list(x.avoid)}<h4>Safety</h4><p>${escapeHtml(x.safety)}</p></div></details>`}
function allExercises(){const out={};Object.entries(catalog).forEach(([section,items])=>items.forEach(x=>out[x[0]]={id:exerciseId(section,x[0]),section,name:x[0],muscle:x[1],sets:x[2],reps:x[3],met:x[4],hint:x[5],instructions:catalogInstructions(section,x),images:catalogImages(section,x[0])}));Object.values(read(STORAGE.customExercises,{})).forEach(x=>{const item={...x,id:x.id||exerciseId(x.section,x.name),instructions:normalizeInstructions(x.instructions),images:normalizeImages(x.images)};out[item.name]=item});return out}
function getExercise(nameOrId){const key=stableSlug(nameOrId);return Object.values(allExercises()).find(x=>x.id===nameOrId||x.name===nameOrId||stableSlug(x.name)===key)}
function initializeLegacyExerciseInstructions(){if(typeof CDC_EXERCISES==='undefined')return;CDC_EXERCISES.forEach(item=>{const section=item.category==='Strength'?(/plank|wall squat|superman/i.test(item.name)?'Isometrics':'Free Weights'):'Aerobics',shape=[item.name,'Full body',1,'minutes',4,`Use a controlled ${item.category.toLowerCase()} effort.`];item.id=item.id||exerciseId('CDC '+item.category,item.name);item.instructions=normalizeInstructions(item.instructions,catalogInstructions(section,shape))})}
function legacyExerciseMatch(nameOrId){if(typeof CDC_EXERCISES==='undefined')return null;const key=stableSlug(nameOrId);return CDC_EXERCISES.find(x=>x.id===nameOrId||stableSlug(x.name)===key)||null}
function safeNumber(value,fallback=0){if(value===0||value==='0')return 0;const parsed=Number(value);return Number.isFinite(parsed)?parsed:fallback}
function deepCopy(value){return JSON.parse(JSON.stringify(value))}
function exerciseSnapshot(value,index=0){const source=typeof value==='string'?(getExercise(value)||legacyExerciseMatch(value)||{name:value}):(value||{}),master=getExercise(source.id||source.name)||legacyExerciseMatch(source.id||source.name)||{},merged={...master,...source},name=String(merged.name||`Exercise ${index+1}`);return{id:String(merged.id||exerciseId(merged.section||'Legacy',name)),name,section:String(merged.section||merged.category||'Legacy / Unavailable'),muscle:String(merged.muscle||''),sets:Math.max(1,Math.trunc(safeNumber(merged.sets,1))),repetitions:String(merged.repetitions??merged.reps??''),duration:Math.max(0,safeNumber(merged.duration,0)),resistance:Math.max(0,safeNumber(merged.resistance??merged.weight,0)),notes:String(merged.notes??merged.hint??''),met:Math.max(0,safeNumber(merged.met,0)),hint:String(merged.hint||''),instructions:deepCopy(normalizeInstructions(merged.instructions,master.instructions)),images:deepCopy(normalizeImages(source.images,master.images)),order:index}}
function normalizeWorkoutDefinition(value,nameHint=''){const raw=Array.isArray(value)?{name:nameHint,exercises:value}:(value&&typeof value==='object'?value:{}),name=String(raw.name||nameHint).trim(),list=raw.exercises??raw.attachedExercises??raw.workoutExercises??raw.selectedExercises??[];return{id:String(raw.id||`workout:${stableSlug(name)}`),name,exercises:(Array.isArray(list)?list:[]).map((item,index)=>exerciseSnapshot(item,index))}}
function normalizedWorkoutDefinitions(){const out={};Object.entries(read(STORAGE.workouts,{})).forEach(([key,value])=>{const workout=normalizeWorkoutDefinition(value,key);if(workout.name)out[workout.name]=workout});return out}
let builderAttachedExercises=[]
function showTab(tab){
  const tabs=['workout','activities','builder'];
  tabs.forEach(t=>{
    const panel=document.getElementById(t+'Tab');
    const button=document.getElementById(t+'TabBtn');
    if(panel) panel.classList.toggle('hidden',t!==tab);
    if(button){
      button.classList.toggle('active',t===tab);
      button.classList.toggle('secondary',t!==tab);
    }
  });
  if(tab==='builder'){
    refreshBuilderDropdown();
    renderCatalog();
    updateSelectedCount();
  }
  if(tab==='activities'){syncActivityDate();renderActivityRows()}
  window.scrollTo({top:0,behavior:'smooth'});
}
function renderCatalog(){const host=document.getElementById('exerciseCatalog');host.innerHTML='';const sections={};Object.values(allExercises()).forEach(x=>(sections[x.section]??=[]).push(x));Object.entries(sections).forEach(([section,items])=>{const det=document.createElement('details');det.className='builder-section';det.open=false;det.innerHTML=`<summary>${escapeHtml(section)} (${items.length})</summary><div class="exercise-options">${items.sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<div class="option"><label><input type="checkbox" class="builderCheck" value="${escapeHtml(x.id)}" onchange="onBuilderSelectionChanged()"><span><b>${escapeHtml(x.name)}</b><span>${escapeHtml(x.muscle)} • ${x.sets} set(s) • ${escapeHtml(x.reps)}</span></span></label>${instructionHtml(x.instructions,x.name,x.images)}</div>`).join('')}</div>`;host.appendChild(det)});syncBuilderChecks()}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function updateSelectedCount(){document.getElementById('selectedCount').textContent=builderAttachedExercises.length}
function syncBuilderChecks(){const ids=new Set(builderAttachedExercises.map(x=>x.id));document.querySelectorAll('.builderCheck').forEach(c=>c.checked=ids.has(c.value));updateSelectedCount()}
function onBuilderSelectionChanged(){const checked=[...document.querySelectorAll('.builderCheck:checked')].map(c=>c.value),existing=new Map(builderAttachedExercises.map(x=>[x.id,x]));builderAttachedExercises=checked.map((id,index)=>exerciseSnapshot(existing.get(id)||getExercise(id)||{id,name:id},index));renderBuilderAttachedExercises()}
function selectAllVisible(value){document.querySelectorAll('.builderCheck').forEach(c=>c.checked=value);onBuilderSelectionChanged()}
function readBuilderAttachedExercises(){const rows=[...document.querySelectorAll('[data-builder-exercise-row]')];if(!rows.length)return deepCopy(builderAttachedExercises);return rows.map((row,index)=>exerciseSnapshot({...builderAttachedExercises[index],sets:row.querySelector('[data-field="sets"]').value,repetitions:row.querySelector('[data-field="repetitions"]').value,duration:row.querySelector('[data-field="duration"]').value,resistance:row.querySelector('[data-field="resistance"]').value,met:row.querySelector('[data-field="met"]').value,notes:row.querySelector('[data-field="notes"]').value},index))}
function renderBuilderAttachedExercises(){const host=document.getElementById('builderAttachedExercises');if(!host)return;host.innerHTML=builderAttachedExercises.length?builderAttachedExercises.map((x,index)=>`<div class="attachedWorkoutExercise" data-builder-exercise-row data-exercise-id="${escapeHtml(x.id)}"><div class="exercise-title">${index+1}. ${escapeHtml(x.name)}</div><div class="row3"><div><label>Sets</label><input data-field="sets" type="number" min="1" value="${x.sets}"></div><div><label>Repetitions</label><input data-field="repetitions" type="text" value="${escapeHtml(x.repetitions)}"></div><div><label>Duration for calorie estimate (minutes)</label><input data-field="duration" type="number" min="0" step="0.1" value="${x.duration}"></div><div><label>Resistance / Weight</label><input data-field="resistance" type="number" min="0" step="0.1" value="${x.resistance}"></div><div><label>MET</label><input data-field="met" type="number" min="0.1" step="0.1" value="${x.met}"></div><div><label>Notes</label><input data-field="notes" type="text" value="${escapeHtml(x.notes)}"></div></div><p class="small">Calories use body weight × MET × duration. Sets, repetitions, and resistance record training volume; they do not directly determine calories.</p>${instructionHtml(x.instructions,x.name,x.images)}<div class="buttons"><button class="secondary" type="button" onclick="moveBuilderExercise(${index},-1)" ${index===0?'disabled':''}>Move Up</button><button class="secondary" type="button" onclick="moveBuilderExercise(${index},1)" ${index===builderAttachedExercises.length-1?'disabled':''}>Move Down</button><button class="danger" type="button" onclick="removeBuilderExercise(${index})">Remove</button></div></div>`).join(''):'<p class="small">No exercises attached yet.</p>';syncBuilderChecks()}
function moveBuilderExercise(index,direction){builderAttachedExercises=readBuilderAttachedExercises();const target=index+direction;if(target<0||target>=builderAttachedExercises.length)return;[builderAttachedExercises[index],builderAttachedExercises[target]]=[builderAttachedExercises[target],builderAttachedExercises[index]];builderAttachedExercises=builderAttachedExercises.map((x,i)=>exerciseSnapshot(x,i));renderBuilderAttachedExercises()}
function removeBuilderExercise(index){builderAttachedExercises=readBuilderAttachedExercises();builderAttachedExercises.splice(index,1);builderAttachedExercises=builderAttachedExercises.map((x,i)=>exerciseSnapshot(x,i));renderBuilderAttachedExercises()}
function addCustomExercise(){const name=document.getElementById('customExerciseName').value.trim(),section=document.getElementById('customExerciseSection').value.trim()||'Custom Exercises',muscle=document.getElementById('customExerciseMuscle').value.trim()||'Custom',sets=Math.max(1,parseInt(document.getElementById('customExerciseSets').value)||1),reps=document.getElementById('customExerciseReps').value.trim()||'reps/time',met=Math.max(1,parseFloat(document.getElementById('customExerciseMet').value)||4),hint=document.getElementById('customExerciseHint').value.trim()||'Use controlled form.',instructionText=document.getElementById('customExerciseInstructions').value.trim();if(!name)return alert('Enter a custom exercise name.');if(getExercise(name)&&!confirm(`An exercise named “${name}” already exists. Replace it?`))return;const custom=read(STORAGE.customExercises,{}),id=exerciseId(section,name);custom[name]={id,section,name,muscle,sets,reps,met,hint,instructions:normalizeInstructions(instructionText||null)};write(STORAGE.customExercises,custom);renderCatalog();const box=[...document.querySelectorAll('.builderCheck')].find(c=>c.value===id);if(box){box.checked=true;onBuilderSelectionChanged()}document.getElementById('customExerciseName').value='';document.getElementById('customExerciseHint').value='';document.getElementById('customExerciseInstructions').value='';alert(`Custom exercise added: ${name}`)}
function refreshBuilderDropdown(){const w=normalizedWorkoutDefinitions(),select=document.getElementById('builderLoad'),cur=select.value;select.innerHTML='<option value="">New workout</option>'+Object.keys(w).sort().map(n=>`<option>${escapeHtml(n)}</option>`).join('');if(w[cur])select.value=cur;else select.value='';loadWorkoutIntoBuilder();refreshWorkoutDropdown()}
function loadWorkoutIntoBuilder(){const name=document.getElementById('builderLoad').value,w=normalizedWorkoutDefinitions(),workout=w[name]||normalizeWorkoutDefinition({},'');document.getElementById('builderName').value=workout.name;builderAttachedExercises=deepCopy(workout.exercises);renderBuilderAttachedExercises()}
function saveWorkoutDefinition(){const name=document.getElementById('builderName').value.trim();if(!name)return alert('Enter a workout name.');builderAttachedExercises=readBuilderAttachedExercises();if(!Array.isArray(builderAttachedExercises))return alert('Workout exercises could not be saved.');if(!builderAttachedExercises.length)return alert('Select at least one exercise.');const w=normalizedWorkoutDefinitions(),loadedName=document.getElementById('builderLoad').value,existing=w[loadedName]||w[name],workout={id:String(existing?.id||`workout:${stableSlug(name)}`),name,exercises:deepCopy(builderAttachedExercises.map((x,index)=>exerciseSnapshot(x,index)))};if(loadedName&&loadedName!==name)delete w[loadedName];w[name]=workout;write(STORAGE.workouts,deepCopy(w));builderAttachedExercises=deepCopy(workout.exercises);document.getElementById('builderLoad').value=name;refreshBuilderDropdown();refreshWorkoutDropdown(name);alert(`Workout saved: ${name}`)}
function deleteWorkoutDefinition(){const name=document.getElementById('builderLoad').value||document.getElementById('builderName').value.trim();if(!name)return alert('Select a saved workout first.');if(!confirm(`Delete workout “${name}”? Saved daily logs will remain.`))return;const w=normalizedWorkoutDefinitions();delete w[name];write(STORAGE.workouts,w);document.getElementById('builderName').value='';builderAttachedExercises=[];renderBuilderAttachedExercises();refreshBuilderDropdown();refreshWorkoutDropdown();renderExercises()}
function refreshWorkoutDropdown(preferred){const w=normalizedWorkoutDefinitions(),sel=document.getElementById('workoutType'),current=preferred||sel.value;sel.innerHTML=Object.keys(w).sort().map(n=>`<option>${escapeHtml(n)}</option>`).join('');if(w[current])sel.value=current}
function dayKey(){return document.getElementById('workoutDate').value}
function getPreviousForExercise(name,date){const days=read(STORAGE.days,{});for(const d of Object.keys(days).filter(x=>x<date).sort().reverse()){const found=(days[d].exercises||[]).find(e=>e.name===name);if(found&&found.sets?.some(s=>s.done))return{date:d,sets:found.sets.filter(s=>s.done)}}return null}
function bestVolumeForExercise(name,date){let best=0;Object.entries(read(STORAGE.days,{})).forEach(([d,day])=>{if(d===date)return;(day.exercises||[]).filter(e=>e.name===name).forEach(e=>{let v=0;(e.sets||[]).forEach(s=>{if(s.done)v+=(parseFloat(s.weight)||0)*(parseFloat(String(s.reps).match(/\d+(\.\d+)?/)?.[0])||0)});best=Math.max(best,v)})});return best}
function renderExercises(data=null){const w=normalizedWorkoutDefinitions(),type=document.getElementById('workoutType').value,attached=deepCopy(w[type]?.exercises||[]),host=document.getElementById('exerciseList'),date=document.getElementById('workoutDate').value;host.innerHTML='';document.getElementById('noWorkoutMessage').classList.toggle('hidden',attached.length>0);attached.forEach((snapshot,i)=>{const x=exerciseSnapshot(snapshot,i),name=x.name,saved=(data?.exercises||[]).find(e=>e.id===x.id||e.name===name)||{};const prev=getPreviousForExercise(name,date);const div=document.createElement('div');div.className='workoutExercise';div.dataset.name=name;div.dataset.exerciseId=x.id;div.innerHTML=`<div class="exercise-title">${escapeHtml(name)}</div><span class="muscle">${escapeHtml(x.section)} • ${escapeHtml(x.muscle)}</span><div class="meta">Target: ${x.sets} set(s) × ${escapeHtml(x.repetitions)}. ${escapeHtml(x.notes||x.hint)}</div><div class="row"><div><label>Duration for calorie estimate (minutes)</label><input type="number" class="exerciseDuration" min="0" step="0.1" value="${saved.duration??x.duration}" oninput="updateSummary();autoSaveDay()"></div><div><label>MET</label><input type="number" class="exerciseMet" min="0.1" step="0.1" value="${saved.met??x.met}" oninput="updateSummary();autoSaveDay()"></div></div>${prev?`<div class="previous"><b>Previous (${prev.date}):</b> ${prev.sets.map((s,j)=>`Set ${j+1}: ${s.weight||'-'} lb × ${s.reps||'-'}`).join(' • ')}</div>`:'<div class="previous"><b>Previous:</b> none saved yet</div>'}${instructionHtml(x.instructions,name,x.images)}<div class="prbox">🏆 New PR for exercise volume</div><div class="badge">Est. calories: <span class="exCalories">0</span></div><div class="badge">Volume: <span class="exVolume">0</span> lb</div><div class="setgrid header"><div>Set</div><div>Weight</div><div>Reps/time</div><div>Inc?</div><div>Done</div></div>${Array.from({length:Number(x.sets)},(_,s)=>{const set=saved.sets?.[s]||{};return `<div class="setgrid"><div class="setno">${s+1}</div><input type="number" class="weight" inputmode="decimal" placeholder="lb" value="${set.weight??x.resistance??''}" oninput="updateSummary()"><input type="text" class="reps" placeholder="${escapeHtml(x.repetitions)}" value="${set.reps??x.repetitions??''}" oninput="updateSummary()"><input type="checkbox" class="increase" ${set.increase?'checked':''} onchange="updateSummary()"><input type="checkbox" class="done" ${set.done?'checked':''} onchange="updateSummary();autoSaveDay()"></div>`}).join('')}`;host.appendChild(div)});updateSummary()}
function updateSummary(){let done=0,total=0,vol=0,wcal=0;const bodyWeight=document.getElementById('bodyWeight').value,exs=[...document.querySelectorAll('.workoutExercise')];exs.forEach(ex=>{let ev=0,ed=0,et=0;ex.querySelectorAll('.setgrid:not(.header)').forEach(r=>{et++;total++;const w=parseFloat(r.querySelector('.weight').value)||0,reps=parseFloat(String(r.querySelector('.reps').value).match(/\d+(\.\d+)?/)?.[0])||0;ev+=w*reps;vol+=w*reps;if(r.querySelector('.done').checked){done++;ed++}});const completion=et?ed/et:0,calories=calculateMetCalories(ex.querySelector('.exerciseMet').value,bodyWeight,ex.querySelector('.exerciseDuration').value)*completion;wcal+=calories;ex.querySelector('.exCalories').textContent=Math.round(calories);ex.querySelector('.exVolume').textContent=Math.round(ev).toLocaleString();ex.querySelector('.prbox').style.display=ev>0&&ev>bestVolumeForExercise(ex.dataset.name,dayKey())?'block':'none'});const acal=getActivityCalories(dayKey());document.getElementById('setsDone').textContent=done;document.getElementById('totalVolume').textContent=Math.round(vol).toLocaleString();document.getElementById('workoutCalories').textContent=Math.round(wcal);document.getElementById('activityCaloriesSummary').textContent=Math.round(acal);document.getElementById('totalCalories').textContent=Math.round(wcal+acal)}
function collectDay(){return{date:dayKey(),type:document.getElementById('workoutType').value,bodyWeight:document.getElementById('bodyWeight').value,minutes:document.getElementById('minutes').value,intensity:document.getElementById('intensity').value,notes:document.getElementById('notes').value,activities:read(STORAGE.activities,{})[dayKey()]||[],exercises:[...document.querySelectorAll('.workoutExercise')].map(ex=>({id:ex.dataset.exerciseId||exerciseId('Legacy',ex.dataset.name),name:ex.dataset.name,duration:ex.querySelector('.exerciseDuration').value,met:ex.querySelector('.exerciseMet').value,sets:[...ex.querySelectorAll('.setgrid:not(.header)')].map(r=>({weight:r.querySelector('.weight').value,reps:r.querySelector('.reps').value,increase:r.querySelector('.increase').checked,done:r.querySelector('.done').checked}))}))}}
function saveDay(showAlert=true){if(!dayKey()){if(showAlert)alert('Select a date.');return false}const days=read(STORAGE.days,{}),d=collectDay(),calories=calculateDailyExerciseCalories(d.date,d);Object.assign(d,calories);days[d.date]=d;write(STORAGE.days,days);renderHistory();const status=document.getElementById('saveStatus');if(status){status.textContent=`Saved ${new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`;clearTimeout(saveDay.statusTimer);saveDay.statusTimer=setTimeout(()=>status.textContent='',2500)}if(showAlert)alert(`Workout saved for ${d.date}`);return true}
function autoSaveDay(){saveDay(false)}
function loadDay(){const d=read(STORAGE.days,{})[dayKey()];if(!d){document.getElementById('notes').value='';renderExercises();updateSummary();return}Object.assign(d,calculateDailyExerciseCalories(dayKey(),d));refreshWorkoutDropdown(d.type);document.getElementById('workoutType').value=d.type;document.getElementById('bodyWeight').value=d.bodyWeight||state.profile?.weight||'';document.getElementById('minutes').value=d.minutes||'';document.getElementById('intensity').value=d.intensity||4.5;document.getElementById('notes').value=d.notes||'';renderExercises(d)}
function clearVisible(){if(!confirm('Clear visible workout fields without deleting saved data?'))return;document.getElementById('notes').value='';renderExercises()}
function deleteCurrentDay(){if(!confirm('Delete the saved workout for this date?'))return;const days=read(STORAGE.days,{});delete days[dayKey()];write(STORAGE.days,days);loadDay();renderHistory()}
function renderHistory(){const host=document.getElementById('history'),days=read(STORAGE.days,{}),keys=Object.keys(days).sort().reverse();if(!keys.length){host.innerHTML='<p class="small">No saved workouts yet.</p>';return}host.innerHTML=keys.map(k=>{const d=days[k];let done=0,total=0,vol=0;(d.exercises||[]).forEach(e=>(e.sets||[]).forEach(s=>{total++;if(s.done)done++;vol+=(parseFloat(s.weight)||0)*(parseFloat(String(s.reps).match(/\d+(\.\d+)?/)?.[0])||0)}));return `<div class="history-item"><b>${d.date}</b> — ${escapeHtml(d.type||'Workout')}<br><span class="small">${done}/${total} sets • ${Math.round(vol).toLocaleString()} lb volume • ${Math.round(getActivityCalories(k))} activity calories</span><br><button onclick="openSaved('${k}')">Open</button></div>`}).join('')}
function openSaved(date){document.getElementById('workoutDate').value=date;loadDay();showTab('workout');window.scrollTo({top:0,behavior:'smooth'})}
function mergedActivities(){const out={};Object.entries(otherActivities).forEach(([cat,items])=>out[cat]=items.map(x=>[x[0],x[1]]));Object.values(read(STORAGE.customActivities,{})).forEach(a=>(out[a.category]??=[]).push([a.name,a.met]));return out}
function renderActivityCategories(preferred){const s=document.getElementById('activityCategory'),all=mergedActivities(),current=preferred||s.value;s.innerHTML=Object.keys(all).sort().map(x=>`<option>${escapeHtml(x)}</option>`).join('');if(all[current])s.value=current;renderActivityOptions()}
function renderActivityOptions(preferred){const cat=document.getElementById('activityCategory').value,items=mergedActivities()[cat]||[],sel=document.getElementById('activitySelect');sel.innerHTML=items.sort((a,b)=>a[0].localeCompare(b[0])).map(([n,m])=>`<option value="${m}">${escapeHtml(n)}</option>`).join('');if(preferred)[...sel.options].some(o=>{if(o.text===preferred){o.selected=true;return true}return false})}
function addCustomActivity(){const name=document.getElementById('customActivityName').value.trim(),category=document.getElementById('customActivityCategory').value.trim()||'Custom',met=Math.max(1,parseFloat(document.getElementById('customActivityMet').value)||3.5);if(!name)return alert('Enter a custom activity name.');const key=`${category}::${name}`.toLowerCase(),custom=read(STORAGE.customActivities,{});custom[key]={name,category,met};write(STORAGE.customActivities,custom);renderActivityCategories(category);renderActivityOptions(name);document.getElementById('customActivityName').value='';alert(`Custom activity saved: ${name}`)}
function syncActivityDate(){document.getElementById('activityDate').value=document.getElementById('workoutDate').value;document.getElementById('activityWeight').value=document.getElementById('bodyWeight').value}
function addActivity(){const date=document.getElementById('activityDate').value,sel=document.getElementById('activitySelect'),name=sel.options[sel.selectedIndex]?.text,met=parseFloat(sel.value),min=parseFloat(document.getElementById('activityMinutes').value),weight=parseFloat(document.getElementById('activityWeight').value);if(!date||!name||!Number.isFinite(min)||min<=0||!Number.isFinite(weight)||weight<=0)return alert('Choose a date and activity, then enter positive minutes and body weight.');const all=read(STORAGE.activities,{});(all[date]??=[]).push({id:Date.now(),name,met,minutes:min,weight});write(STORAGE.activities,all);renderActivityRows();updateSummary()}
function activityCalories(a){return calculateMetCalories(a.met,a.weight,a.minutes)}
function getActivityCalories(date){return (read(STORAGE.activities,{})[date]||[]).reduce((s,a)=>s+activityCalories(a),0)}
function renderActivityRows(){const date=document.getElementById('activityDate').value,rows=read(STORAGE.activities,{})[date]||[],host=document.getElementById('activityRows');host.innerHTML=rows.length?rows.map(a=>`<div class="activity-row activity-grid"><div><b>${escapeHtml(a.name)}</b><div class="small">MET ${a.met} • ${a.weight} lb</div></div><div>${a.minutes} min</div><div>${Math.round(activityCalories(a))} cal</div><button class="danger" onclick="deleteActivity('${date}',${a.id})">Delete</button></div>`).join(''):'<p class="small">No activities saved for this date.</p>';document.getElementById('activityTotalMinutes').textContent=Math.round(rows.reduce((s,a)=>s+(parseFloat(a.minutes)||0),0));document.getElementById('activityTotalCalories').textContent=Math.round(rows.reduce((s,a)=>s+activityCalories(a),0));updateSummary()}
function deleteActivity(date,id){if(!confirm('Delete this saved activity?'))return;const all=read(STORAGE.activities,{});all[date]=(all[date]||[]).filter(a=>a.id!==id);write(STORAGE.activities,all);renderActivityRows()}
function clearActivitiesForDate(){const date=document.getElementById('activityDate').value;if(!confirm(`Delete all other activities for ${date}?`))return;const all=read(STORAGE.activities,{});delete all[date];write(STORAGE.activities,all);renderActivityRows()}
function saveActivitiesToDay(){const date=document.getElementById('activityDate').value;if(!date)return alert('Select a date.');const days=read(STORAGE.days,{}),rows=read(STORAGE.activities,{})[date]||[];days[date]??={date,type:'Other Activities',bodyWeight:document.getElementById('activityWeight').value,minutes:0,intensity:1,notes:'',exercises:[]};days[date].activities=rows;Object.assign(days[date],calculateDailyExerciseCalories(date,days[date]));write(STORAGE.days,days);renderHistory();const status=document.getElementById('activitySaveStatus');status.textContent=`Saved to ${date}`;clearTimeout(saveActivitiesToDay.timer);saveActivitiesToDay.timer=setTimeout(()=>status.textContent='',2500);updateSummary()}
function refreshWorkoutTracker(preferredDate){ensureDefaults();renderCatalog();refreshBuilderDropdown();refreshWorkoutDropdown();const chosen=preferredDate||document.getElementById('workoutDate').value||todayISO();const profileWeight=parseFloat(state.profile&&state.profile.weight)||'';document.getElementById('bodyWeight').value=profileWeight;document.getElementById('activityWeight').value=profileWeight;document.getElementById('workoutDate').value=chosen;document.getElementById('activityDate').value=chosen;if(!document.getElementById('workoutDate').dataset.workoutBound){document.getElementById('workoutDate').addEventListener('change',()=>{loadDay();document.getElementById('activityDate').value=dayKey()});document.getElementById('activityDate').addEventListener('change',renderActivityRows);document.getElementById('workoutDate').dataset.workoutBound='true';}renderActivityCategories();loadDay();renderHistory();renderActivityRows()}
initializeLegacyExerciseInstructions();refreshWorkoutTracker();
